 //! GitHub release client used by `derrick upgrade`.

 use reqwest::header::{ACCEPT, USER_AGENT};
 use serde::{Deserialize, Deserializer};
 use thiserror::Error;

 const RELEASES_URL: &str = "https://api.github.com/repos/lgulliver/derrick/releases?per_page=1";

 /// A GitHub release returned by the latest-release endpoint.
 #[derive(Debug, Deserialize)]
 pub struct Release {
     #[serde(deserialize_with = "deserialize_semver_tag_name")]
     tag_name: String,
     assets: Vec<ReleaseAsset>,
 }

 impl Release {
     /// Returns the release tag name.
     #[must_use]
     pub fn tag_name(&self) -> &str {
         &self.tag_name
     }

     /// Returns assets attached to the release.
     #[must_use]
     pub fn assets(&self) -> &[ReleaseAsset] {
         &self.assets
     }
 }

 /// A downloadable GitHub release asset.
 #[derive(Debug, Deserialize)]
 pub struct ReleaseAsset {
     name: String,
 }

 impl ReleaseAsset {
     /// Returns the asset name.
     #[must_use]
     pub fn name(&self) -> &str {
         &self.name
     }
 }

 /// Errors returned by the GitHub release client.
 #[derive(Debug, Error)]
 pub enum ReleaseClientError {
     /// The HTTP request or response decoding failed.
     #[error(transparent)]
     Http(#[from] reqwest::Error),
     /// GitHub returned no releases for Derrick.
     #[error("GitHub returned no releases for lgulliver/derrick")]
     NoRelease,
 }

 /// Reqwest-backed client for GitHub release metadata.
 #[derive(Debug, Clone)]
 pub struct ReqwestReleaseClient {
     client: reqwest::Client,
     releases_url: &'static str,
 }

 impl Default for ReqwestReleaseClient {
     fn default() -> Self {
         Self {
             client: reqwest::Client::new(),
             releases_url: RELEASES_URL,
         }
     }
 }

 impl ReqwestReleaseClient {
     /// Creates a release client using the default GitHub endpoint.
     #[must_use]
     pub fn new() -> Self {
         Self::default()
     }

     /// Fetches the latest Derrick release from GitHub.
     ///
     /// This method performs network I/O against GitHub's releases API.
     pub async fn latest_release(&self) -> Result<Release, ReleaseClientError> {
         let mut releases: Vec<Release> = self
             .client
             .get(self.releases_url)
             .header(USER_AGENT, concat!("derrick/", env!("CARGO_PKG_VERSION")))
             .header(ACCEPT, "application/vnd.github+json")
             .send()
             .await?
             .error_for_status()?
             .json()
             .await?;

         releases.pop().ok_or(ReleaseClientError::NoRelease)
     }
 }

 fn deserialize_semver_tag_name<'de, D>(deserializer: D) -> Result<String, D::Error>
 where
     D: Deserializer<'de>,
 {
     let tag_name = String::deserialize(deserializer)?;
     Ok(semver_tag_name(&tag_name))
 }

 fn semver_tag_name(tag_name: &str) -> String {
     let trimmed = tag_name.trim();
     if let Some(version) = trimmed.strip_prefix('v') {
         version.to_owned()
     } else if let Some(nightly) = trimmed.strip_prefix("nightly-") {
         format!("0.0.0-nightly.{nightly}")
     } else {
         trimmed.to_owned()
     }
 }

 #[cfg(test)]
 mod tests {
     use super::{semver_tag_name, Release};

     type TestResult<T = ()> = Result<T, Box<dyn std::error::Error>>;

     #[test]
     fn release_deserializes_tag_and_asset_names() -> TestResult {
         let release: Release = serde_json::from_str(
             r#"{
                 "tag_name": "v1.2.3",
                 "assets": [
                     { "name": "derrick-aarch64-apple-darwin.tar.gz" }
                 ]
             }"#,
         )?;

         assert_eq!(release.tag_name(), "1.2.3");
         match release.assets() {
             [asset] => assert_eq!(asset.name(), "derrick-aarch64-apple-darwin.tar.gz"),
             assets => assert_eq!(assets.len(), 1),
         }
         Ok(())
     }

     #[test]
     fn nightly_release_tags_are_normalized_to_semver_prereleases() {
         assert_eq!(
             semver_tag_name("nightly-20260524"),
             "0.0.0-nightly.20260524"
         );
         assert_eq!(
             semver_tag_name("nightly-20260518.1"),
             "0.0.0-nightly.20260518.1"
         );
     }
 }

